import json, subprocess, sys, random, itertools

def naive(request):
    """Independent brute-force: enumerate every execution path recursively."""
    mem0=list(request['memory']); threads=[list(map(tuple,p)) for p in request['threads']]
    n=len(threads); ni=[len(p) for p in threads]
    outcomes=set()
    def go(pcs,bufs,mem,reads):
        term = all(pcs[t]==ni[t] and not bufs[t] for t in range(n))
        if term:
            outcomes.add((tuple(tuple(r) for r in reads),tuple(mem))); return
        for t in range(n):
            if pcs[t]>=ni[t]: continue
            ins=threads[t][pcs[t]]; op=ins[0]; b=bufs[t]
            if op=='store':
                go(pcs[:t]+(pcs[t]+1,)+pcs[t+1:], bufs[:t]+(b+((ins[1],ins[2],ins[3]),),)+bufs[t+1:], mem, reads)
            elif op=='load':
                a,w=ins[1],ins[2]; v=0
                for i in range(w-1,-1,-1):
                    aa=a+i; by=None
                    for sa,sw,sv in reversed(b):
                        if sa<=aa<sa+sw: by=(sv>>(8*(aa-sa)))&0xFF; break
                    if by is None: by=mem[aa]
                    v=(v<<8)|by
                go(pcs[:t]+(pcs[t]+1,)+pcs[t+1:], bufs, mem, reads[:t]+(reads[t]+(v,),)+reads[t+1:])
            elif op=='fence':
                if not b: go(pcs[:t]+(pcs[t]+1,)+pcs[t+1:], bufs, mem, reads)
            elif op=='xchg':
                if not b:
                    a,w,val=ins[1],ins[2],ins[3]; old=0
                    for i in range(w-1,-1,-1): old=(old<<8)|mem[a+i]
                    nm=list(mem)
                    for i in range(w): nm[a+i]=(val>>(8*i))&0xFF
                    go(pcs[:t]+(pcs[t]+1,)+pcs[t+1:], bufs, nm, reads[:t]+(reads[t]+(old,),)+reads[t+1:])
        for t in range(n):
            if bufs[t]:
                a,w,v=bufs[t][0]; nm=list(mem)
                for i in range(w): nm[a+i]=(v>>(8*i))&0xFF
                go(pcs, bufs[:t]+(bufs[t][1:],)+bufs[t+1:], nm, reads)
    go(tuple([0]*n), tuple([()]*n), mem0, tuple([()]*n))
    return {"outcomes":[{"reads":[list(r) for r in rd],"memory":list(m)} for rd,m in outcomes]}

